const karbohidrat_g = 50; // contoh: 50 gram
const protein_g = 20; // contoh: 20 gram
const lemak_g = 10; // contoh: 10 gram

const kalori_karbo = karbohidrat_g * 4.1;
const kalori_protein = protein_g * 4.1;
const kalori_lemak = lemak_g * 9.3;

const total = kalori_karbo + kalori_protein + kalori_lemak;
console.log("Kalori dari karbohidrat:", kalori_karbo);
console.log("Kalori dari protein:", kalori_protein);
console.log("Kalori dari lemak:", kalori_lemak);
console.log("Total kalori:", total);

function jenisPencernaan(input) {
  const s = input.toLowerCase();
  const mekanisKeys = ["gigi","lidah","peristaltik","otot","mengunyah","pengadukan"];
  const kimiawiKeys = ["enzim","amilase","ptyalin","hcl","pepsin","renin","maltosa","pepton"];
  if (kimiawiKeys.some(k => s.includes(k))) return "kimiawi";
  if (mekanisKeys.some(k => s.includes(k))) return "mekanis";
  return "tidak dikenali";
}

const testInputs = ["gigi", "lidah", "enzim ptyalin", "HCl", "gerak peristaltik", "pepsin"];
for (const x of testInputs) {
  console.log(x, "->", jenisPencernaan(x));
}
